char * getDebugScriptBuildDateString(void)

{
  int debugState;
  char *resultString;
  uint seconds;
  uint minutes;
  uint day;
  uint hour;
  uint finalDigit;
  undefined4 intToStrBuffer1;
  undefined4 intToStrBuffer2;
  
  intToStrBuffer1 = gAsciiConversionTemp1;
  intToStrBuffer2 = gAsciiConversionTemp2;
  debugState = isDebugDisabled();
  if (debugState == 0) {
    resultString = BUILDUP_UNDEFINED;
  }
  else {
    seconds = gScriptBuildTimestamp >> 5;
    builtin_strncpy(gDebugStringBuf,"Buildup:  199",0xe);
    resultString = gDebugStringBuf;
    finalDigit = gScriptBuildTimestamp & 0xf;
    hour = gScriptBuildTimestamp >> 0xb;
    day = gScriptBuildTimestamp >> 0x10;
    minutes = gScriptBuildTimestamp >> 0x15;
    intToAscii((gScriptBuildTimestamp >> 0x19) % 10,&intToStrBuffer1);
    strcat(gDebugStringBuf,(char *)&intToStrBuffer1);
    strcat(gDebugStringBuf,FORWARD_SLASH);
    intToAscii(minutes & 0xf,&intToStrBuffer1,10);
    strcat(gDebugStringBuf,(char *)&intToStrBuffer1);
    strcat(gDebugStringBuf,FORWARD_SLASH);
    intToAscii(day & 0x1f,&intToStrBuffer1,10);
    strcat(gDebugStringBuf,(char *)&intToStrBuffer1);
    strcat(gDebugStringBuf,SPACE);
    intToAscii(hour & 0x1f,&intToStrBuffer1,10);
    strcat(gDebugStringBuf,(char *)&intToStrBuffer1);
    strcat(gDebugStringBuf,COLON);
    intToAscii(seconds & 0x3f,&intToStrBuffer1,10);
    strcat(gDebugStringBuf,(char *)&intToStrBuffer1);
    strcat(gDebugStringBuf,COLON);
    intToAscii(finalDigit,&intToStrBuffer1,10);
    strcat(gDebugStringBuf,(char *)&intToStrBuffer1);
    strcat(gDebugStringBuf,_NEWLINE_);
  }
  return resultString;
}



int intToAscii(int value,char *buffer,int base)

{
  char *endPtr;
  int digitCount;
  int charCount;
  byte digitBuffer [25];
  char asciiOffset;
  int digitIndex;
  
  if (value < 0) {
    value = -value;
    *buffer = '-';
    buffer = buffer + 1;
  }
  digitCount = 0;
  charCount = 0;
  while (value != 0) {
    if (base == 0) {
      trap(0x1c00);
    }
    if ((base == -1) && (value == -0x80000000)) {
      trap(0x1800);
    }
    digitIndex = digitCount + 1;
    digitCount = digitCount + 1;
    charCount = charCount + 1;
    digitBuffer[digitIndex] = (byte)(value % base);
    value = value / base;
  }
  endPtr = buffer + digitCount;
  if (digitCount == 0) {
    digitBuffer[1] = 0;
    digitCount = 1;
    endPtr = buffer + 1;
  }
  *endPtr = '\0';
  for (; 0 < digitCount; digitCount = digitCount + -1) {
    asciiOffset = '0';
    if (9 < digitBuffer[digitCount]) {
      asciiOffset = '7';
    }
    *buffer = digitBuffer[digitCount] + asciiOffset;
    buffer = buffer + 1;
  }
  return charCount;
}



