void decompressLZSS(int compressedDataPtr,byte *outputBuffer)

{
  int compressedLength;
  undefined *dictPtr;
  byte *dictWritePtr;
  int copyLengthCounter;
  uint dictIndex;
  int inputOffset;
  uint bitmask;
  byte *inputCursor;
  byte bitmaskByte;
  byte decompressedByte;
  byte refHeaderByte;
  
  compressedLength = readLittleEndian32(compressedDataPtr + 2);
  inputOffset = 0xfed;
  dictPtr = &lzssWindowEnd;
  do {
    *dictPtr = 0;
    inputOffset = inputOffset + -1;
    dictPtr = dictPtr + -1;
  } while (-1 < inputOffset);
  dictIndex = 0xfee;
  bitmaskByte = *(byte *)(compressedDataPtr + 6);
  inputOffset = 1;
  compressedLength = compressedLength + -5;
  inputCursor = (byte *)(compressedDataPtr + 7);
  if (compressedLength != 1) {
    do {
      bitmask = bitmaskByte | 0xff00;
      do {
        if ((bitmask & 1) == 0) {
          bitmaskByte = *inputCursor;
          if (inputOffset + 1 == compressedLength) {
            return;
          }
          refHeaderByte = inputCursor[1];
          inputOffset = inputOffset + 2;
          inputCursor = inputCursor + 2;
          if (inputOffset == compressedLength) {
            return;
          }
          copyLengthCounter = 0;
          do {
            dictWritePtr = &lzssWindow + dictIndex;
            dictIndex = dictIndex + 1 & 0xfff;
            decompressedByte =
                 (&lzssWindow)
                 [((uint)bitmaskByte | (refHeaderByte & 0xf0) << 4) + copyLengthCounter & 0xfff];
            copyLengthCounter = copyLengthCounter + 1;
            *outputBuffer = decompressedByte;
            *dictWritePtr = decompressedByte;
            outputBuffer = outputBuffer + 1;
          } while (copyLengthCounter <= (int)((refHeaderByte & 0xf) + 2));
        }
        else {
          bitmaskByte = *inputCursor;
          inputOffset = inputOffset + 1;
          inputCursor = inputCursor + 1;
          if (inputOffset == compressedLength) {
            return;
          }
          *outputBuffer = bitmaskByte;
          outputBuffer = outputBuffer + 1;
          dictWritePtr = &lzssWindow + dictIndex;
          dictIndex = dictIndex + 1 & 0xfff;
          *dictWritePtr = bitmaskByte;
        }
        bitmask = bitmask >> 1;
      } while ((bitmask & 0x100) != 0);
      bitmaskByte = *inputCursor;
      inputOffset = inputOffset + 1;
      inputCursor = inputCursor + 1;
    } while (inputOffset != compressedLength);
  }
  return;
}



// look for C3 header

void checkAndUnpackAmpack(char *buffer)

{
  char *messageData;
  
  if (*buffer == -0x3d) {
    if (buffer[1] == -1) {
      decompressLZSS();
      return;
    }
    messageData = DATA_EQUALS;
  }
  else {
    messageData = (char *)0x0;
  }
  reportIssue("Unpack Err:  no Ampack data",messageData,0,0,0);
  return;
}



int readLittleEndian32(byte *data)

{
  return (uint)*data + (uint)data[1] * 0x100 + (uint)data[2] * 0x10000 + (uint)data[3] * 0x1000000;
}



void loadProgdata(undefined4 fileIndex,undefined4 resourceType)

{
  char *dataString;
  
  loadByFileIdGroupId(fileIndex,resourceType,&rawProgdataFileBuffer,0x30000);
  if (rawProgdataFileBuffer == 0xc3) {
    if (usingCompressedFiles == -1) {
      decompressLZSS(&rawProgdataFileBuffer,&decompressedOutputBuffer);
      return;
    }
    dataString = DATA_EQUALS;
  }
  else {
    dataString = (char *)0x0;
  }
  reportIssue("Unpack Err:  no Ampack data",dataString,0,0,0);
                    // WARNING: Read-only address (ram,0x80138000) is written
  return;
}



