void startVibrationEffect(int vibeEffectId)

{
  int result;
  undefined *vibrationBuffer;
  undefined4 bufferLength;
  short *vibeEffectHeader;
  undefined tempAsciiBuffer [32];
  
  result = isVibrationEnabled();
  if (result == 1) {
    result = getVibrationDeviceType(0);
    if (result == 2) {
      vibrationBuffer = &fallbackVibrationBuffer;
      bufferLength = 3;
    }
    else {
      vibrationBuffer = &primaryVibrationBuffer;
      bufferLength = 2;
    }
    sendVibrationCommand(0,vibrationBuffer,bufferLength);
    result = *(int *)(&vibrationData + vibeEffectId * 4);
    if (result == 0) {
      intToAscii(vibeEffectId,tempAsciiBuffer,10);
      reportIssue("No Vibrate Data",tempAsciiBuffer,0,0,0);
      result = *(int *)(&vibrationData + vibeEffectId * 4);
    }
    vibeEffectHeader = (short *)(&vibrationData + result);
    if (*vibeEffectHeader != 0) {
      vibrationSegmentIndex = &vibrationDataStart + result;
      vibrationSegmentTimer1 = 0;
      vibrationSegmentTimer2 = 0;
    }
    if (*(short *)(&vibrationDataStart + result) != 0) {
      vibrationFrameCounter1 = 0;
      vibrationFrameCounter2 = 0;
      vibrationStateFlag = (undefined *)((int)vibeEffectHeader + *vibeEffectHeader + 2);
    }
    queueVibrationPlayback(0,&DAT_80061a5c);
  }
  return;
}



