int getNextInterpolatedByte(int *reader)

{
  int segmentLength;
  int deltaScaled;
  
  segmentLength = reader[2];
  reader[2] = segmentLength + 1;
  if (reader[3] <= segmentLength + 1) {
    segmentLength = *reader;
    reader[2] = 0;
    *reader = segmentLength + 2;
    if (*(byte *)(segmentLength + 3) == 0xff) {
      *reader = 0;
      *(undefined *)(reader + 1) = 0;
      *(undefined *)((int)reader + 5) = 0;
      reader[3] = 1;
    }
    else {
      reader[3] = (*(byte *)(segmentLength + 3) + 1) * 4;
      *(undefined *)(reader + 1) = *(undefined *)(segmentLength + 2);
      *(undefined *)((int)reader + 5) = *(undefined *)(segmentLength + 4);
    }
  }
  deltaScaled = ((uint)*(byte *)((int)reader + 5) - (uint)*(byte *)(reader + 1)) * reader[2];
  segmentLength = reader[3];
  if (segmentLength == 0) {
    trap(0x1c00);
  }
  if ((segmentLength == -1) && (deltaScaled == -0x80000000)) {
    trap(0x1800);
  }
  return ((uint)*(byte *)(reader + 1) + deltaScaled / segmentLength & 0x7f) << 1;
}



