void updateVibrationAndInput(void)

{
  byte vibrationByte;
  int vibrationActiveResult;
  
  vibrationTriggerFlag = 0;
  if (vibrationStateFlag != 0) {
    vibrationByte = getNextInterpolatedByte(&vibrationStateFlag);
    if (vibrationByte < 0x4b) {
      primaryVibrationBuffer = 0;
    }
    else {
      primaryVibrationBuffer = 0xff;
    }
  }
  if ((vibrationSegmentIndex != 0) &&
     (vibrationCycleCounter = getNextInterpolatedByte(&vibrationSegmentIndex),
     99 < vibrationCycleCounter)) {
    vibrationTriggerFlag = 1;
  }
  if ((vibrationEffectFrameCount != 0) &&
     (vibrationActiveResult = isVibrationActive(), vibrationActiveResult == 0)) {
    vibrationEffectFrameCount = vibrationEffectFrameCount + -1;
    startVibrationEffect(3);
  }
  if (((newInputPressedMask2P & 1) == 0) && ((newInputPressedMask2P & 4) != 0)) {
    debugOnConroller2L2Press();
  }
  return;
}



