int loadByFileIdGroupId(int fileIndex,undefined4 resourceType,undefined4 destBuffer,int maxSize)

{
  int totalFilesInGroup;
  undefined4 startSector;
  int sectorSize;
  undefined fileNumStr [32];
  undefined resourceTypeStr [32];
  
  totalFilesInGroup = getFileCountInGroup(resourceType);
  if (totalFilesInGroup <= fileIndex) {
    fileIndex = getFileCountInGroup(resourceType);
    fileIndex = fileIndex + -1;
  }
  getCdFileSectorInfo(&startSector,fileIndex,resourceType);
  if ((maxSize == 0) || (sectorSize <= maxSize)) {
    SetCdBusyStatus(1);
    loadRawSectorData(startSector,sectorSize,destBuffer);
    WaitForCdIdle(0);
  }
  else {
    intToAscii(fileIndex,fileNumStr,10);
    intToAscii(resourceType,resourceTypeStr,10);
    reportIssue("File Size Over \n","FileNum = ",fileNumStr,"\nUser ID = ",resourceTypeStr);
    sectorSize = 0;
  }
  return sectorSize;
}



