void setCdAudioMonoStereo(undefined *mixSettings,undefined volume)

{
  if (soundMode == '\x01') {
    *mixSettings = volume;
    mixSettings[1] = volume;
    mixSettings[2] = 0;
    mixSettings[3] = 0;
    return;
  }
  *mixSettings = volume;
  mixSettings[1] = 0;
  mixSettings[2] = volume;
  mixSettings[3] = 0;
  return;
}



void playTitleScreenCutscene(int movieId)

{
  undefined4 startSector;
  
  SetCdBusyStatus(3);
  startSector = getSectorForMovieId(movieId,0);
  playScriptedMovieCutscene
            (startSector,(&movieSegmentDuration)[movieId * 5],1,(&movieFadeStartY)[movieId * 5],
             (&movieFadeHeights)[movieId * 5],(&movieEffectFlags)[movieId * 5],0,1,1,0,1,0xffffffff)
  ;
  return;
}



void startScriptedMovieWithFade
               (int movieId,int offset,int fadeStartY,undefined4 fadeHeight,undefined4 fadeMode)

{
  undefined4 movieHandle;
  int playDuration;
  
  cancelVibrationEffect();
  SetCdBusyStatus(3);
  playDuration = offset + fadeStartY;
  if (fadeStartY == 0) {
    playDuration = (&movieSegmentDuration)[movieId * 5];
  }
  movieHandle = getSectorForMovieId(movieId,0);
  playScriptedMovieCutscene
            (movieHandle,playDuration,1,(&movieFadeStartY)[movieId * 5],
             (&movieFadeHeights)[movieId * 5],(&movieEffectFlags)[movieId * 5],offset,fadeHeight,0,0
             ,fadeMode,0xffffffff);
  return;
}



