void SetCdBusyStatus(int newCdBusyStatus,char *operationLabelOut)

{
  int cdSyncResult;
  char *busyLabelMessage;
  
  switch(newCdBusyStatus) {
  case 1:
    operationLabelOut = s_Load_80061b10;
    break;
  case 2:
    operationLabelOut = s_LoadF_80061b18;
    break;
  case 3:
    operationLabelOut = MOVIE;
    break;
  case 4:
    operationLabelOut = MOVIEF;
    break;
  case 5:
    operationLabelOut = s_Cd_Da_80061b30;
    break;
  case 6:
    operationLabelOut = s_SeekB_80061b38;
    break;
  case 7:
    operationLabelOut = s_SeekF_80061b40;
  }
  switch(cdTransferReady) {
  default:
    goto switchD_8001bbf4_caseD_0;
  case 1:
    busyLabelMessage = "\nBusy=Load";
    break;
  case 2:
    if (newCdBusyStatus - 1U < 2) {
      WaitForCdIdle(0);
      cdTransferReady = newCdBusyStatus;
      return;
    }
    busyLabelMessage = "\nBusy=LoadF";
    break;
  case 3:
    busyLabelMessage = "\nBusy=Movie";
    break;
  case 4:
    stopScriptedMovieDecoder(newCdBusyStatus,operationLabelOut);
    cdTransferReady = newCdBusyStatus;
    return;
  case 6:
    busyLabelMessage = "\nBusy=SeekB";
    break;
  case 7:
    do {
      cdSyncResult = CdSync(1,(u_char *)0x0);
    } while (cdSyncResult != 2);
    goto switchD_8001bbf4_caseD_0;
  }
  reportIssue("Cd Head Err\nRequest=",operationLabelOut,busyLabelMessage,0,0);
switchD_8001bbf4_caseD_0:
  cdTransferReady = newCdBusyStatus;
  return;
}



