      faceSlotId = (uint)(byte)(&characterSlotTable)[faceSlotOffset];
      if (2 < faceSlotId) {
        reportError(ERROR_COLON,"exec without enter");
        return;
      }
      faceSlotIndexTimes10 = faceSlotId * 0x14;
      (&portraitSlotStateFlags)[faceSlotIndexTimes10] =
           *(undefined *)(&characterFacingDirection + characterId * 0xb);
      (&faceSlotBoxPosX)[faceSlotId * 10] = (&messageBoxPosX)[characterId * 0xb];
