      (&portraitSlotBoxWidth)[faceSlotId * 10] = (&messageBoxWidth)[characterId * 0xb];
      (&portraitSlotBoxHeight)[faceSlotId * 10] = (&messageBoxHeight)[characterId * 0xb];
      (&faceSlotPoseId)[faceSlotId * 10] = (&characterPoseIdTable)[characterId * 0xb];
      (&faceSlotPoseVariant)[faceSlotId * 10] = (&characterPoseVariantTable)[characterId * 0xb];
      (&faceSlotFaceId)[faceSlotId * 10] = (&characterFaceIdTable)[characterId * 0xb];
      (&faceSlotFacingDirection)[faceSlotIndexTimes10] = (&characterFacingDirection)[faceSlotOffset]
      ;
      (&faceSlotBlendMode)[faceSlotIndexTimes10] = (&characterBlendModeTable)[faceSlotOffset];
      (&portraitSlotHasWindow)[faceSlotIndexTimes10] = (&characterWindowWidthTable)[faceSlotOffset];
      if ((&characterFaceNeedsRedraw)[faceSlotOffset] == '\x01') {
        (&faceSlotIsVisibleFlag)[faceSlotIndexTimes10] = 3;
        (&characterFaceNeedsRedraw)[faceSlotOffset] = 0;
        (&characterDialogueLineIndex)[characterId * 4] = 0;
        scriptIsExecuting = 0;
      }
