                    // get data from 8 bit memory pool 2
    puVar3 = &scriptVar8;
getTableData:
    bVar1 = *scriptInstructionPointer;
    scriptInstructionPointer = scriptInstructionPointer + 1;
    result = (uint)(ushort)puVar3[bVar1] << 0x10;
    goto returnValue;
  case 2:
