    bVar1 = *scriptInstructionPointer;
    pbVar2 = scriptInstructionPointer + 1;
    scriptInstructionPointer = scriptInstructionPointer + 2;
    result = (uint)(ushort)(&scriptVar16)[CONCAT11(bVar1,*pbVar2)] << 0x10;
    goto returnValue;
