    pbVar2 = scriptInstructionPointer + 1;
    scriptInstructionPointer = scriptInstructionPointer + 2;
    decodedOperand = (uint)CONCAT11(bVar1,*pbVar2);
    break;
  case 5:
                    // return oprend as 16 bit int
    bVar1 = *scriptInstructionPointer;
    scriptInstructionPointer = scriptInstructionPointer + 1;
    result = (uint)bVar1 << 0x10;
    goto returnValue;
  case 7:
