// WARNING: Globals starting with '_' overlap smaller symbols at the same address

void copyScriptToRuntimeBuffer(int scriptType)

{
  undefined *sourceBaseAddress;
  undefined1 *sourcePtr;
  int byteIndex;
  uint scriptLength;
  
  if (_rawProgdataFileBuffer == -0x3d) {
    checkAndUnpackAmpack(&rawProgdataFileBuffer,&decompressedOutputBuffer);
    sourceBaseAddress = &ampackUnpackedBuffer;
  }
  else {
    sourceBaseAddress = &rawScriptDataBuffer;
  }
  scriptLength = (uint)CONCAT11(*(undefined *)(((uint)sourceBaseAddress | 0x8000) + 6),
                                *(undefined *)(((uint)sourceBaseAddress | 0x8000) + 7));
  if (((scriptType != 0) && (scriptType == 1)) && (0x8000 < scriptLength)) {
    reportIssue(" taiwa script larger than 0x8000",0,0,0,0);
  }
  byteIndex = 0;
  sourcePtr = &decompressedOutputBuffer;
  do {
    if (scriptType == 0) {
                    // main script
      (&mainScriptRuntimeBuffer)[byteIndex] = *sourcePtr;
    }
    else if (scriptType == 1) {
                    // taiwa script
      (&taiwaScriptRuntimeBuffer)[byteIndex] = *sourcePtr;
    }
    byteIndex = byteIndex + 1;
    sourcePtr = sourcePtr + 1;
  } while (byteIndex <= (int)scriptLength);
  return;
}



