void computeMovementStep(int startX,int startY,int targetX,int targetY,int *stepX,int *stepY)

{
  targetX = targetX - startX;
  targetY = targetY - startY;
  if (targetX < 0) {
    targetX = -targetX;
  }
  if (targetY < 0) {
    targetY = -targetY;
  }
  if (targetX <= targetY) {
    if (targetY == 0) {
      trap(0x1c00);
    }
    if ((targetY == -1) && (targetX << 8 == -0x80000000)) {
      trap(0x1800);
    }
    *stepX = (targetX << 8) / targetY;
    *stepY = 0x100;
    return;
  }
  if (targetX == 0) {
    trap(0x1c00);
  }
  if ((targetX == -1) && (targetY << 8 == -0x80000000)) {
    trap(0x1800);
  }
  *stepX = 0x100;
  *stepY = (targetY << 8) / targetX;
  return;
}



