{
  short tileY;
  undefined *tilePtr;
  uint *primitiveLinkPtr;
  int column;
  byte *debugCharPtr;
  int row;
  byte charTileByte;
  
  if (((debugDisplayPageId != 0) || (debugViewMode != 0)) || (scriptTimingFrameCount != 0)) {
    debugCharPtr = &debugTextBuffer;
    row = 0;
    primitiveLinkPtr = (uint *)(activeDrawContext + 0xc1e0);
    do {
      column = 0;
      tilePtr = (undefined *)((int)primitiveLinkPtr + 0xd);
      do {
        tileY = debugTileBaseY + (short)row;
        *(short *)(tilePtr + -5) = debugTileBaseX + (short)column;
        *(short *)(tilePtr + -3) = tileY;
        column = column + 8;
        tilePtr[-1] = (char)((*debugCharPtr & 0xf) << 3);
        charTileByte = *debugCharPtr;
        debugCharPtr = debugCharPtr + 1;
        *tilePtr = (char)((int)((charTileByte & 0xf0) - 0x20) >> 1);
        tilePtr = tilePtr + 0x10;
                    // Probable PsyQ macro: addPrim().
        *primitiveLinkPtr = *primitiveLinkPtr & 0xff000000 | *renderListPtr & 0xffffff;
        *renderListPtr = *renderListPtr & 0xff000000 | (uint)primitiveLinkPtr & 0xffffff;
        primitiveLinkPtr = primitiveLinkPtr + 4;
      } while (column < 0x100);
      row = row + 8;
    } while (row < 0xa0);
    AddPrim(renderListPtr,(void *)(activeDrawContext + 0x2cd0));
  }
  return;
}



void drawTwoDigitNumber(uint *renderListHead,uint highlightSlotId,short number)

{
  int highlightOffset;
  int digitTileIndex;
  uint *tensDigitPrim;
  uint *onesDigitPrim;
  undefined2 digitDrawPosY;
  
  highlightSlotId = highlightSlotId & 0xffff;
  highlightOffset = highlightSlotId * 0x14;
  dateDrawPosX = *(short *)(&highlightSlotOffsetX + highlightOffset);
  dateDrawPosY = *(undefined2 *)(&highlightSlotOffsetY + highlightOffset);
  if (*(short *)(&highlightSlotEnabled + highlightOffset) != 0) {
    tensDigitPrim =
         (uint *)(activeDrawContext +
                 (uint)(ushort)(&highlightPrimStartTile)[highlightSlotId * 10] * 0x10 + 0x51c0);
    setShadeTexFlag(tensDigitPrim,0);
    setPrimitiveSemiTrans(tensDigitPrim,(&highlightTransparency)[highlightOffset]);
    digitTileIndex = ((int)number / 10) * 4;
    *(undefined *)(tensDigitPrim + 3) = (&digitTileU)[digitTileIndex];
    *(undefined *)((int)tensDigitPrim + 0xd) = (&digitTileV)[digitTileIndex];
    digitDrawPosY = dateDrawPosY;
    *(short *)(tensDigitPrim + 2) = dateDrawPosX;
    *(undefined2 *)((int)tensDigitPrim + 10) = digitDrawPosY;
    *(undefined2 *)((int)tensDigitPrim + 0xe) = (&highlightClut)[highlightSlotId * 10];
    dateDrawPosX = dateDrawPosX + (ushort)(byte)(&digitTileWidth)[digitTileIndex];
    *tensDigitPrim = *tensDigitPrim & 0xff000000 | *renderListHead & 0xffffff;
    onesDigitPrim = tensDigitPrim + 4;
    *renderListHead = *renderListHead & 0xff000000 | (uint)tensDigitPrim & 0xffffff;
    setShadeTexFlag(onesDigitPrim,0);
    setPrimitiveSemiTrans(onesDigitPrim,(&highlightTransparency)[highlightOffset]);
    digitTileIndex = ((int)number % 10) * 4;
    *(undefined *)(tensDigitPrim + 7) = (&digitTileU)[digitTileIndex];
    *(undefined *)((int)tensDigitPrim + 0x1d) = (&digitTileV)[digitTileIndex];
    *(undefined2 *)((int)tensDigitPrim + 0x1a) = dateDrawPosY;
    highlightOffset = activeDrawContext;
    *(short *)(tensDigitPrim + 6) = dateDrawPosX;
    *(undefined2 *)((int)tensDigitPrim + 0x1e) = (&highlightClut)[highlightSlotId * 10];
    dateDrawPosX = dateDrawPosX + (ushort)(byte)(&digitTileWidth)[digitTileIndex];
    *onesDigitPrim = *onesDigitPrim & 0xff000000 | *renderListHead & 0xffffff;
    *renderListHead = *renderListHead & 0xff000000 | (uint)onesDigitPrim & 0xffffff;
    AddPrim(renderListHead,(void *)(highlightOffset + highlightSlotId * 0xc + 0x9cc0));
  }
  return;
}



