void loadPortraitAnimationScript(ushort *script,undefined4 scriptId)

{
  int numDecodedPortraits;
  undefined2 *decodedIndex;
  int decodedPtr;
  ushort *scriptPtr;
  undefined2 decodedPortraitList [12];
  ushort command;
  bool continueParsing;
  undefined2 decodedPortraitId;
  
  continueParsing = true;
  defaultTintBComponent = 0x80;
  defaultTintGComponent = 0x80;
  defaultTintRComponent = 0x80;
  currentPortraitPaletteId = 0;
  portraitOffsetXData = portraitStartOffsetX;
  portraitOffsetYData = portraitStartOffsetY;
  do {
    command = *script;
    scriptPtr = script;
    if (command == 0xff) {
      portraitOffsetYData = portraitOffsetYData + 8;
      portraitOffsetXData = portraitStartOffsetX;
advanceToNextScriptEntry:
      script = scriptPtr + 1;
    }
    else {
      if ((short)command < 0x100) {
        if (command == 0) {
          continueParsing = false;
        }
        else {
handlePortraitOrPalette:
          if ((ushort)(*script + 0xef01) < 0x701) {
            currentPortraitPaletteId = *script >> 8 & 7;
          }
          else {
            allocatePortraitAnimSlot(scriptId,*script);
            portraitOffsetXData = portraitOffsetXData + portraitXSpacing;
          }
        }
        goto advanceToNextScriptEntry;
      }
      if (command != 0x1ff) {
        if (command != 0xd0a) goto handlePortraitOrPalette;
        portraitOffsetYData = portraitOffsetYData + portraitYSpacing;
        portraitOffsetXData = portraitStartOffsetX;
        goto advanceToNextScriptEntry;
      }
      decodedIndex = decodedPortraitList;
      decodedPtr = 0;
      numDecodedPortraits = decodePortraitAnimBlock(script[1],decodedIndex);
      scriptPtr = script + 1;
      if (numDecodedPortraits < 1) goto advanceToNextScriptEntry;
      do {
        decodedPortraitId = *decodedIndex;
        decodedIndex = decodedIndex + 1;
        allocatePortraitAnimSlot(scriptId,decodedPortraitId);
        decodedPtr = decodedPtr + 1;
        portraitOffsetXData = portraitOffsetXData + portraitXSpacing;
      } while (decodedPtr * 0x10000 >> 0x10 < numDecodedPortraits);
      script = script + 2;
    }
    if (!continueParsing) {
      currentPortraitPaletteId = 0;
      return;
    }
  } while( true );
}



