void waitWithDialogueUI(int frameCount)

{
  int frameIndex;
  
  frameIndex = 0;
  if (0 < frameCount) {
    do {
      frameIndex = frameIndex + 1;
      drawTaiwaScreenUI(activeDrawContext + 0x70);
      stepFrameAndSwapBuffers();
    } while (frameIndex < frameCount);
  }
  return;
}



